  "codebook": {
    "clarification": "Include: (1) announcements of federal grants, appropriations, loans, contracts, facilities, military missions, designations, disaster declarations, or favorable agency decisions benefiting the senator's state, even without an explicit 'I secured it' - the senator's own announcement of the benefit is itself a credit-claiming vehicle; (2) explicit role statements such as 'I helped secure,' 'at my request,' 'funding I requested,' or 'my amendment was adopted'; (3) claims that the senator's letter, appeal, pressure, or negotiation produced a favorable agency or administration decision; (4) touting previously enacted legislation, adopted amendments, or provisions the senator authored/championed in bills that passed a chamber or became law, when framed as delivering benefits; (5) touting past wins of funding or resources for the state. Legislative milestones count only when the senator claims responsibility for something actually adopted or passed (e.g., an adopted amendment, a passed bill they authored); merely introducing, cosponsoring, or advocating a bill does not count.",
    "definition": "Credit-claiming occurs when a senator claims personal or shared responsibility for a concrete government action that delivers (or has delivered) particularized benefits - federal funds, grants, projects, facilities, designations, disaster declarations, military missions, favorable agency decisions, or enacted/adopted legislative provisions - to their state, district, or favored constituencies. The essential feature is the senator generating the belief that they are responsible for a desirable governmental outcome, not merely taking a position on policy.",
    "negative_clarification": "Exclude: (1) position statements on national policy, including praise or blame of the President, administration, parties, or other actors; (2) explanations or defenses of the senator's own votes without a claim of producing a beneficial outcome; (3) introductions, cosponsorships, or endorsements of legislation that has not passed or been adopted - these are advocacy/position-taking even if the bill would deliver benefits; (4) commemorations, condolences, remembrances, resolutions honoring others, awards presented to constituents, and third-party awards recognizing the senator's voting record; (5) announcements of town meetings, hearings, or nominations without claimed benefits; (6) oversight statements, investigations, or letters criticizing or pressuring agencies when no achieved result is claimed; (7) welcoming favorable developments without any claim of responsibility and without a final delivered benefit; (8) general credit to one's party or to broad national policies.",
    "negative_examples": [
      {
        "document_id": "656",
        "explanation": "Kerry's statement on the Dubai ports deal is entirely criticism of the Bush administration's port security failures. Attacking an opponent and taking a position on a policy controversy involves no claim of responsibility for any delivered benefit - pure position-taking."
      },
      {
        "document_id": "4531",
        "explanation": "Thune and Clinton announce they have introduced a bill to extend child care for fallen soldiers' families. Because the bill has only been introduced - nothing has passed or been delivered - this is legislative advocacy, the key boundary case distinguishing bill introduction (0) from adopted/passed provisions (1)."
      },
      {
        "document_id": "597",
        "explanation": "Lugar presents a health and fitness award named after him to honor community groups. Ceremonial recognition of others confers no government benefit and involves no claim of responsibility for governmental action - it is advertising/commemoration, not credit-claiming."
      }
    ],
    "positive_examples": [
      {
        "document_id": "2318",
        "explanation": "Durbin writes to Illinois officials about the South Suburban Airport and explicitly states 'I helped secure an expedited environmental review from the federal government and facilitated the return of the project to the national priority list for federal funding' - a textbook explicit claim of personal responsibility for favorable federal actions benefiting his state."
      },
      {
        "document_id": "2627",
        "explanation": "Talent announces that 'the Senate has approved his request for $1.5 million dollars' for a University of Missouri research center, with university officials thanking him for securing the money - the classic appropriations credit-claiming press release."
      },
      {
        "document_id": "873",
        "explanation": "Medicare's administrator waived late-enrollment penalties for hurricane-affected Louisiana seniors only after Landrieu's letter and delegation pressure; the release claims the agency 'finally come to its senses' in response to her intervention - credit-claiming for prompting a favorable agency decision for constituents."
      }
    ]
  }
}
